 * Unit tests for org.apache.commons.codec.binary.Base64.encodeBase64String
 */
public class Base64_encodeBase64String_TriageGen0Test {







    @Test
    public void testEncodeBase64String_SingleByte() {
        byte[] input = new byte[] { (byte) 0x00 };
        // 0x00 in Base64 is "AA=="
        String expected = "AA==";
        String actual = Base64.encodeBase64String(input);
        assertEquals("Encoding a single zero byte should return 'AA=='", expected, actual);
    }




